  1→/**
  2→ * tools.cli.ts — thin CLI dispatcher for Prism query tools
  3→ *
  4→ * Usage (from web/ directory):
  5→ *   node --import tsx server/prism/tools.cli.ts <toolName> '<jsonArgs>'
  6→ *
  7→ * toolName: queryMarkers | scanMetricOverFrames | getFrameCallTree |
  8→ *           getThreadTimeline | correlateFrameSets |
  9→ *           scanPeakMarkers | queryFrameCounters | aggregateSubtree |
 10→ *           drillDownMarker | getSourceForSymbol |
 11→ *           querySchedState | queryAtraceSlices | queryFrameTimeline |
 12→ *           queryCpuFreq | getPerfettoCallTree | correlateFrameSchedCpu |
 13→ *           queryCallTreeSubtree | querySliceDeltas | queryOffCpuAttribution |
 14→ *           queryGcAllocByModule |
 15→ *           queryMarkersMultiState | queryFrameSummaryMultiState |
 16→ *           queryThreadsMultiState | queryAggCallTreeMultiState |
 17→ *           queryUnityMarkers
 18→ *
 19→ * SINGLE mode:
 20→ *   node --import tsx server/prism/tools.cli.ts single '{"tool":"querySchedState","args":{"role":"cur"}}'
 21→ *
 22→ * BATCH mode (amortizes tsx cold-start across many queries — MUCH faster):
 23→ *   node --import tsx server/prism/tools.cli.ts batch '[{"tool":"queryMarkers","args":{...}}, ...]'
 24→ *   → returns a JSON array of { tool, args, ok, data|error } in the same order.
 25→ *
 26→ * runId defaults to 'unity-outside-stressmove' if not provided in jsonArgs.
 27→ */
 28→
 29→import { openPrismDb } from './db.js';
 30→import {
 31→  queryMarkers,
 32→  scanMetricOverFrames,
 33→  getFrameCallTree,
 34→  getThreadTimeline,
 35→  correlateFrameSets,
 36→  scanPeakMarkers,
 37→  queryFrameCounters,
 38→  aggregateSubtree,
 39→  drillDownMarker,
 40→  getSourceForSymbol,
 41→  querySchedState,
 42→  queryAtraceSlices,
 43→  queryFrameTimeline,
 44→  queryCpuFreq,
 45→  getPerfettoCallTree,
 46→  correlateFrameSchedCpu,
 47→  queryCallTreeSubtree,
 48→  querySliceDeltas,
 49→  queryOffCpuAttribution,
 50→  queryGcAllocByModule,
 51→  queryMarkersMultiState,
 52→  queryFrameSummaryMultiState,
 53→  queryThreadsMultiState,
 54→  queryAggCallTreeMultiState,
 55→  queryUnityMarkers,
 56→} from './tools.js';
 57→import type Database from 'better-sqlite3';
 58→
 59→const PERFETTO_JSON_TOOL_NAMES = new Set([
 60→  'querySchedState',
 61→  'queryAtraceSlices',
 62→  'queryFrameTimeline',
 63→  'queryCpuFreq',
 64→  'getPerfettoCallTree',
 65→  'correlateFrameSchedCpu',
 66→  'queryCallTreeSubtree',
 67→  'querySliceDeltas',
 68→  'queryOffCpuAttribution',
 69→  'queryGcAllocByModule',
 70→]);
 71→
 72→// WT-044: Unity 多态/单态 JSON 工具集（不需要 sqlite，从 preprocess-result.json 读）
 73→const UNITY_JSON_TOOL_NAMES = new Set([
 74→  'queryMarkersMultiState',
 75→  'queryFrameSummaryMultiState',
 76→  'queryThreadsMultiState',
 77→  'queryAggCallTreeMultiState',
 78→  'queryUnityMarkers',
 79→]);
 80→
 81→type ToolRunner = (db: Database.Database | null, args: Record<string, unknown>) => unknown;
 82→
 83→const TOOLS: Record<string, ToolRunner> = {
 84→  queryMarkers:          (db, a) => queryMarkers(db!, a as unknown as Parameters<typeof queryMarkers>[1]),
 85→  scanMetricOverFrames:  (db, a) => scanMetricOverFrames(db!, a as unknown as Parameters<typeof scanMetricOverFrames>[1]),
 86→  getFrameCallTree:      (db, a) => getFrameCallTree(db!, a as unknown as Parameters<typeof getFrameCallTree>[1]),
 87→  getThreadTimeline:     (db, a) => getThreadTimeline(db!, a as unknown as Parameters<typeof getThreadTimeline>[1]),
 88→  correlateFrameSets:    (db, a) => correlateFrameSets(db!, a as unknown as Parameters<typeof correlateFrameSets>[1]),
 89→  scanPeakMarkers:       (db, a) => scanPeakMarkers(db!, a as unknown as Parameters<typeof scanPeakMarkers>[1]),
 90→  queryFrameCounters:    (db, a) => queryFrameCounters(db!, a as unknown as Parameters<typeof queryFrameCounters>[1]),
 91→  aggregateSubtree:      (db, a) => aggregateSubtree(db!, a as unknown as Parameters<typeof aggregateSubtree>[1]),
 92→  drillDownMarker:       (db, a) => drillDownMarker(db!, a as unknown as Parameters<typeof drillDownMarker>[1]),
 93→  getSourceForSymbol:    (db, a) => getSourceForSymbol(db!, a as unknown as Parameters<typeof getSourceForSymbol>[1]),
 94→  querySchedState:       (db, a) => querySchedState(db, a as unknown as Parameters<typeof querySchedState>[1]),
 95→  queryAtraceSlices:     (db, a) => queryAtraceSlices(db, a as unknown as Parameters<typeof queryAtraceSlices>[1]),
 96→  queryFrameTimeline:    (db, a) => queryFrameTimeline(db, a as unknown as Parameters<typeof queryFrameTimeline>[1]),
 97→  queryCpuFreq:          (db, a) => queryCpuFreq(db, a as unknown as Parameters<typeof queryCpuFreq>[1]),
 98→  getPerfettoCallTree:   (db, a) => getPerfettoCallTree(db, a as unknown as Parameters<typeof getPerfettoCallTree>[1]),
 99→  correlateFrameSchedCpu:(db, a) => correlateFrameSchedCpu(db, a as unknown as Parameters<typeof correlateFrameSchedCpu>[1]),
100→  queryCallTreeSubtree:  (db, a) => queryCallTreeSubtree(db, a as unknown as Parameters<typeof queryCallTreeSubtree>[1]),
101→  querySliceDeltas:      (db, a) => querySliceDeltas(db, a as unknown as Parameters<typeof querySliceDeltas>[1]),
102→  queryOffCpuAttribution:(db, a) => queryOffCpuAttribution(db, a as unknown as Parameters<typeof queryOffCpuAttribution>[1]),
103→  queryGcAllocByModule:  (db, a) => queryGcAllocByModule(db, a as unknown as Parameters<typeof queryGcAllocByModule>[1]),
104→  queryMarkersMultiState:      (db, a) => queryMarkersMultiState(db, a as unknown as Parameters<typeof queryMarkersMultiState>[1]),
105→  queryFrameSummaryMultiState:(db, a) => queryFrameSummaryMultiState(db, a as unknown as Parameters<typeof queryFrameSummaryMultiState>[1]),
106→  queryThreadsMultiState:      (db, a) => queryThreadsMultiState(db, a as unknown as Parameters<typeof queryThreadsMultiState>[1]),
107→  queryAggCallTreeMultiState:  (db, a) => queryAggCallTreeMultiState(db, a as unknown as Parameters<typeof queryAggCallTreeMultiState>[1]),
108→  queryUnityMarkers:           (db, a) => queryUnityMarkers(db, a as unknown as Parameters<typeof queryUnityMarkers>[1]),
109→};
110→
111→function usage(): never {
112→  console.error(
113→    'Usage: node --import tsx server/prism/tools.cli.ts <toolName> \'<jsonArgs>\'\n' +
114→    'Tools: ' + Object.keys(TOOLS).join(', ') + '\n' +
115→    'runId defaults to "' + DEFAULT_RUN_ID + '" if not specified in args.'
116→  );
117→  process.exit(1);
118→}
119→
120→const [, , toolName, rawArgs] = process.argv;
121→
122→if (!toolName || (toolName !== 'single' && toolName !== 'batch' && !TOOLS[toolName])) {
123→  console.error(`Unknown tool: ${toolName ?? '(none)'}`);
124→  usage();
125→}
126→
127→function toolNeedsDb(name: string): boolean {
128→  // perfetto JSON 工具 + unity 多态/单态 JSON 工具都不需要 sqlite
129→  return !PERFETTO_JSON_TOOL_NAMES.has(name) && !UNITY_JSON_TOOL_NAMES.has(name);
130→}
131→
132→function injectDefaultRunId(name: string, args: Record<string, unknown>): void {
133→  if (args.runId) return; // 已有 runId，不覆盖
134→  // 从环境变量读取（由 explore-service / narrative-service 在 spawn CLI 时注入）
135→  const envRunId = process.env.PRISM_RUN_ID;
136→  if (envRunId) {
137→    args.runId = envRunId;
138→    return;
139→  }
140→  // 没有环境变量 → 报错，杜绝硬编码默认值
141→  throw new Error(
142→    `Tool "${name}" requires runId but none provided. ` +
143→    `Pass runId in args or set PRISM_RUN_ID env var.`
144→  );
145→}
146→
147→// ── SINGLE mode: JSON envelope { tool, args } ───────────────────────
148→if (toolName === 'single') {
149→  let item: { tool?: string; args?: Record<string, unknown> };
150→  try {
151→    item = rawArgs ? JSON.parse(rawArgs) : {};
152→  } catch {
153→    console.error('Failed to parse single args as JSON object:', rawArgs);
154→    process.exit(1);
155→  }
156→  const t = item.tool;
157→  const a: Record<string, unknown> = { ...(item.args ?? {}) };
158→  if (!t || !TOOLS[t]) {
159→    console.error(`Unknown tool: ${t ?? '(none)'}`);
160→    process.exit(1);
161→  }
162→  injectDefaultRunId(t, a);
163→  const db = toolNeedsDb(t) ? openPrismDb() : null;
164→  try {
165→    const result = TOOLS[t](db, a);
166→    console.log(JSON.stringify(result, null, 2));
167→  } catch (err) {
168→    console.error('Tool error:', err instanceof Error ? err.message : String(err));
169→    process.exit(1);
170→  } finally {
171→    db?.close();
172→  }
173→  process.exit(0);
174→}
175→
176→// ── BATCH mode: run many queries in one process (amortize tsx cold-start) ──
177→if (toolName === 'batch') {
178→  let batch: Array<{ tool: string; args?: Record<string, unknown> }>;
179→  try {
180→    batch = rawArgs ? JSON.parse(rawArgs) : [];
181→  } catch {
182→    console.error('Failed to parse batch args as JSON array:', rawArgs);
183→    process.exit(1);
184→  }
185→  if (!Array.isArray(batch)) {
186→    console.error('batch expects a JSON array of { tool, args }');
187→    process.exit(1);
188→  }
189→  const needsDb = batch.some(item => item?.tool && TOOLS[item.tool] && toolNeedsDb(item.tool));
190→  const db = needsDb ? openPrismDb() : null;
191→  const results: unknown[] = [];
192→  try {
193→    for (const item of batch) {
194→      const t = item?.tool;
195→      const a: Record<string, unknown> = { ...(item?.args ?? {}) };
196→      if (!t || !TOOLS[t]) {
197→        results.push({ tool: t ?? '(none)', args: a, ok: false, error: `Unknown tool: ${t ?? '(none)'}` });
198→        continue;
199→      }
200→      injectDefaultRunId(t, a);
201→      try {
202→        const out = TOOLS[t](toolNeedsDb(t) ? db : null, a) as { data?: unknown };
203→        // tools return { data, provenance }; surface data + keep provenance
204→        results.push({ tool: t, args: a, ok: true, result: out });
205→      } catch (err) {
206→        results.push({ tool: t, args: a, ok: false, error: err instanceof Error ? err.message : String(err) });
207→      }
208→    }
209→    console.log(JSON.stringify(results, null, 2));
210→  } finally {
211→    db?.close();
212→  }
213→  process.exit(0);
214→}
215→
216→let args: Record<string, unknown>;
217→try {
218→  args = rawArgs ? JSON.parse(rawArgs) : {};
219→} catch {
220→  console.error('Failed to parse args as JSON:', rawArgs);
221→  process.exit(1);
222→}
223→
224→injectDefaultRunId(toolName, args);
225→
226→const db = toolNeedsDb(toolName) ? openPrismDb() : null;
227→try {
228→  const result = TOOLS[toolName](db, args);
229→  console.log(JSON.stringify(result, null, 2));
230→} catch (err) {
231→  console.error('Tool error:', err instanceof Error ? err.message : String(err));
232→  process.exit(1);
233→} finally {
234→  db?.close();
235→}
