3604→function loadUnityRun(args: UnityJsonToolArgs): LoadedUnityRun {
3605→  const { role, runDir } = resolveUnityRunDir(args);
3606→  const resultPath = path.join(runDir, 'preprocess-result.json');
3607→  const summaryPath = path.join(runDir, 'preprocess-summary.json');
3608→  if (!fs.existsSync(resultPath)) {
3609→    throw new Error(`Unity preprocess-result.json not found: ${resultPath}`);
3610→  }
3611→  if (!fs.existsSync(summaryPath)) {
3612→    throw new Error(`Unity preprocess-summary.json not found: ${summaryPath}`);
3613→  }
3614→  const result = JSON.parse(fs.readFileSync(resultPath, 'utf8')) as Record<string, unknown>;
3615→  const summary = JSON.parse(fs.readFileSync(summaryPath, 'utf8')) as Record<string, unknown>;
3616→  const markers = (Array.isArray(result.markers) ? result.markers : []).map((m: unknown) => {
3617→    const r = asRecord(m);
3618→    return {
3619→      name: typeof r.name === 'string' ? r.name : String(r.name ?? ''),
3620→      msSelfMean: asNumber(r.msSelfMean) ?? 0,
3621→      msTotalMean: asNumber(r.msTotalMean) ?? 0,
3622→      percentOfFrame: asNumber(r.percentOfFrame) ?? 0,
3623→      count: asNumber(r.count) ?? 0,
3624→      presentOnFrameCount: asNumber(r.presentOnFrameCount) ?? 0,
3625→      thread: typeof r.thread === 'string' ? r.thread : '',
3626→      depth: asNumber(r.depth) ?? 0,
3627→      spikeRatio: asNumber(r.spikeRatio),
3628→      mustReport: r.mustReport === true,
3629→      mustReportReason: typeof r.mustReportReason === 'string' ? r.mustReportReason : undefined,
3630→    } as UnityMarkerRow;
3631→  });
3632→  const aggregatedCallTrees = (Array.isArray(result.aggregatedCallTrees) ? result.aggregatedCallTrees : [])
3633→    .map((t: unknown) => t as UnityAggCallTree);
3634→  const frameSummary = asRecord(result.frameSummary) as unknown as UnityFrameSummary;
3635→  const threads = (Array.isArray(result.threads) ? result.threads : []).map((t: unknown) => t as UnityThreadSummary);
3636→  const runId = args.runId ?? `unity-${role}`;
3637→  return { runId, role, runDir, resultPath, summaryPath, result, summary, markers, aggregatedCallTrees, frameSummary, threads };
3638→}
