4103→// ── Unity 单态工具（兼容单态查询，LLM 在单态时用） ────────────────────
4104→// 读 single role 的 preprocess-result.json，提供和 multi 工具对称的单态查询能力。
4105→// 当 LLM 检测到单态（只有 1 个样本）时，用这些工具而不是 multi 工具。
4106→
4107→export interface QueryUnitySingleArgs extends UnityJsonToolArgs {
4108→  thread?: string;
4109→  topN?: number;
4110→  sortBy?: 'selfMs' | 'totalMs' | 'percentOfFrame';
4111→}
4112→
4113→export interface QueryUnitySingleResult {
4114→  data: {
4115→    available: boolean;
4116→    frameCount: number;
4117→    rows: UnityMarkerRow[];
4118→  };
4119→  provenance: Provenance;
4120→}
4121→
4122→export function queryUnityMarkers(
4123→  _db: Database.Database | null | undefined,
4124→  args: QueryUnitySingleArgs
4125→): QueryUnitySingleResult {
4126→  const run = loadUnityRun({ ...args, role: args.role ?? 'single' });
4127→  const threadFilter = args.thread?.toLowerCase();
4128→  const sortBy = args.sortBy ?? 'selfMs';
4129→  const topN = Math.min(args.topN ?? 20, 100);
4130→  let rows = run.markers;
4131→  if (threadFilter) rows = rows.filter(m => m.thread.toLowerCase().includes(threadFilter));
4132→  rows.sort((a, b) => {
4133→    if (sortBy === 'totalMs') return b.msTotalMean - a.msTotalMean;
4134→    if (sortBy === 'percentOfFrame') return b.percentOfFrame - a.percentOfFrame;
4135→    return b.msSelfMean - a.msSelfMean;
4136→  });
4137→  return {
4138→    data: {
4139→      available: rows.length > 0,
4140→      frameCount: run.frameSummary?.count ?? 0,
4141→      rows: rows.slice(0, topN),
4142→    },
4143→    provenance: unityProvenance('queryUnityMarkers', args, run),
4144→  };
4145→}
